// Parse HTML to Notion blocks WITH FORMATTING AND IMAGES
const input = $input.first().json;
const htmlContent = input.htmlContent;
const pageTitle = input.pageTitle || 'Untitled';
const sourceUrl = input.sourceUrl || '';

let html = htmlContent;

// Clean HTML - remove non-content elements
html = html.replace(/<script[^>]*>[\s\S]*?<\/script>/gi, '');
html = html.replace(/<style[^>]*>[\s\S]*?<\/style>/gi, '');
html = html.replace(/<nav[^>]*>[\s\S]*?<\/nav>/gi, '');
html = html.replace(/<header[^>]*>[\s\S]*?<\/header>/gi, '');
html = html.replace(/<footer[^>]*>[\s\S]*?<\/footer>/gi, '');
html = html.replace(/<!--[\s\S]*?-->/g, '');

// Extract title
if (pageTitle === 'Untitled') {
  const titleMatch = html.match(/<title[^>]*>([^<]+)<\/title>/i);
  if (titleMatch) pageTitle = titleMatch[1].trim();
}

const blocks = [];
let match;

// Helper: Parse rich text with formatting
function parseRichText(htmlText) {
  const richText = [];
  let text = htmlText;

  // Handle bold: <strong>, <b>
  text = text.replace(/<strong[^>]*>([\s\S]*?)<\/strong>/gi, '**$1**');
  text = text.replace(/<b[^>]*>([\s\S]*?)<\/b>/gi, '**$1**');

  // Handle italic: <em>, <i>
  text = text.replace(/<em[^>]*>([\s\S]*?)<\/em>/gi, '*$1*');
  text = text.replace(/<i[^>]*>([\s\S]*?)<\/i>/gi, '*$1*');

  // Handle code: <code>
  text = text.replace(/<code[^>]*>([\s\S]*?)<\/code>/gi, '`$1`');

  // Extract links: <a href="url">text</a>
  const linkRegex = /<a[^>]+href="([^"]+)"[^>]*>([\s\S]*?)<\/a>/gi;
  const results = [];
  let lastIndex = 0;

  while ((match = linkRegex.exec(text)) !== null) {
    const url = match[1];
    const linkText = match[2];

    const preceding = text.substring(lastIndex, match.index).trim();
    if (preceding) {
      results.push({ type: 'text', text: { content: preceding } });
    }

    results.push({ type: 'text', text: { content: linkText }, href: url });
    lastIndex = linkRegex.lastIndex;
  }

  const remaining = text.substring(lastIndex).trim();
  if (remaining) {
    results.push({ type: 'text', text: { content: remaining } });
  }

  if (results.length === 0 && text.trim()) {
    results.push({ type: 'text', text: { content: text.trim() } });
  }

  return results;
}

// Helper: Clean HTML tags but preserve content
function cleanText(text) {
  return text.replace(/<[^>]+>/g, ' ').replace(/\s+/g, ' ').trim();
}

// Helper: Validate URL
function isValidUrl(url) {
  try {
    new URL(url);
    return true;
  } catch {
    return false;
  }
}

// Create title block
blocks.push({
  type: 'heading_1',
  heading_1: { rich_text: [{ type: 'text', text: { content: pageTitle.substring(0, 1900) } }] }
});

// ============================================
// EXTRACT IMAGES FIRST (before other content)
// ============================================
const imgRegex = /<img[^>]+>/gi;
const processedImgIndices = new Set();
let imgIndex = 0;

while ((match = imgRegex.exec(html)) !== null) {
  const imgTag = match[0];

  // Extract src
  const srcMatch = imgTag.match(/src=["']([^"']+)["']/i);
  if (!srcMatch) continue;

  let srcUrl = srcMatch[1];

  // Skip data URLs (base64) - Notion doesn't support them directly
  if (srcUrl.startsWith('data:')) {
    continue;
  }

  // Make URLs absolute if relative
  if (srcUrl.startsWith('//')) {
    srcUrl = 'https:' + srcUrl;
  }

  if (!isValidUrl(srcUrl)) {
    continue;
  }

  // Extract alt text as caption
  const altMatch = imgTag.match(/alt=["']([^"']+)["']/i);
  const altText = altMatch ? altMatch[1] : '';

  // Extract title as caption if alt not present
  const titleMatch = imgTag.match(/title=["']([^"']+)["']/i);
  const captionText = altText || (titleMatch ? titleMatch[1] : '');

  // Create image block
  const imageBlock = {
    type: 'image',
    image: {
      type: 'external',
      external: {
        url: srcUrl
      },
      caption: []
    }
  };

  // Add caption if available
  if (captionText && captionText.length > 0) {
    imageBlock.image.caption = [{ type: 'text', text: { content: captionText.substring(0, 2000) } }];
  }

  blocks.push(imageBlock);
  imgIndex++;
}

// Extract headings with formatting
const headingTags = [
  { tag: 'h1', type: 'heading_1' },
  { tag: 'h2', type: 'heading_2' },
  { tag: 'h3', type: 'heading_3' },
  { tag: 'h4', type: 'heading_3' },
  { tag: 'h5', type: 'heading_3' },
  { tag: 'h6', type: 'heading_3' }
];

for (const ht of headingTags) {
  const regex = new RegExp(`<${ht.tag}[^>]*>([\s\S]*?)<\/${ht.tag}>`, 'gi');
  while ((match = regex.exec(html)) !== null) {
    const content = match[1];
    if (content && cleanText(content)) {
      blocks.push({
        type: ht.type,
        [ht.type]: { rich_text: parseRichText(content) }
      });
    }
  }
}

// Extract paragraphs with formatting
const paraRegex = /<p[^>]*>([\s\S]*?)<\/p>/gi;
while ((match = paraRegex.exec(html)) !== null) {
  const content = match[1];
  if (content && cleanText(content).length >= 5) {
    blocks.push({
      type: 'paragraph',
      paragraph: { rich_text: parseRichText(content) }
    });
  }
}

// Extract list items
const liRegex = /<li[^>]*>([\s\S]*?)<\/li>/gi;
while ((match = liRegex.exec(html)) !== null) {
  const content = match[1];
  if (content && cleanText(content)) {
    blocks.push({
      type: 'bulleted_list_item',
      bulleted_list_item: { rich_text: parseRichText(content) }
    });
  }
}

// Extract blockquotes
const quoteRegex = /<blockquote[^>]*>([\s\S]*?)<\/blockquote>/gi;
while ((match = quoteRegex.exec(html)) !== null) {
  const content = match[1];
  if (content && cleanText(content)) {
    blocks.push({
      type: 'quote',
      quote: { rich_text: parseRichText(content) }
    });
  }
}

// Extract figure captions
const figCaptionRegex = /<figcaption[^>]*>([\s\S]*?)<\/figcaption>/gi;
while ((match = figCaptionRegex.exec(html)) !== null) {
  const content = match[1];
  if (content && cleanText(content)) {
    blocks.push({
      type: 'paragraph',
      paragraph: { rich_text: [{ type: 'text', text: { content: `Figure: ${cleanText(content)}` } }] }
    });
  }
}

// If no blocks created
if (blocks.length === 0) {
  const text = cleanText(html);
  if (text) {
    blocks.push({
      type: 'paragraph',
      paragraph: { rich_text: [{ type: 'text', text: { content: text } }] }
    });
  }
}

// Split long text blocks (2000 char limit) - skip images
const MAX_CHUNK = 1900;
const allChunks = [];

blocks.forEach(block => {
  const type = block.type;

  // Images don't need chunking
  if (type === 'image') {
    allChunks.push(block);
    return;
  }

  const richText = block[type]?.rich_text || [];
  let combinedText = richText.map(rt => rt.text?.content || '').join('');

  if (combinedText.length <= MAX_CHUNK) {
    allChunks.push(block);
  } else {
    const chunks = combinedText.match(new RegExp(`.{1,${MAX_CHUNK}}`, 'g')) || [];
    chunks.forEach((chunk) => {
      allChunks.push({
        type: type,
        [type]: { rich_text: [{ type: 'text', text: { content: chunk } }] }
      });
    });
  }
});

// Deduplicate consecutive blocks
const deduped = [];
allChunks.forEach(block => {
  const prev = deduped[deduped.length - 1];

  if (block.type === 'image' && prev?.type === 'image') {
    // Check for duplicate image URLs
    const prevUrl = prev.image?.external?.url || '';
    const currUrl = block.image?.external?.url || '';
    if (prevUrl === currUrl) return;
  }

  if (prev && prev.type === block.type && block.type !== 'image') {
    const prevContent = (prev[prev.type]?.rich_text || []).map(rt => rt.text?.content || '').join('');
    const currContent = (block[block.type]?.rich_text || []).map(rt => rt.text?.content || '').join('');
    if (prevContent === currContent) return;
  }

  deduped.push(block);
});

// Group into chunks of 100 (Notion API limit)
const BLOCK_LIMIT = 100;
const blockGroups = [];
for (let i = 0; i < deduped.length; i += BLOCK_LIMIT) {
  blockGroups.push(deduped.slice(i, i + BLOCK_LIMIT));
}

// Count image blocks
const imageCount = deduped.filter(b => b.type === 'image').length;

return [{
  json: {
    pageTitle: pageTitle,
    sourceUrl: sourceUrl,
    publishedAt: new Date().toISOString(),
    databaseId: '2eff939bda2080858aabe82fd3be2a25',
    blockGroups: blockGroups,
    totalBlocks: deduped.length,
    imageCount: imageCount,
    textBlockCount: deduped.length - imageCount,
    totalGroups: blockGroups.length,
    hasBlocks: deduped.length > 0
  }
}];

// Loop through block groups and append to Notion
const data = $input.first().json;
const pageId = data.pageId;
const blockGroups = data.blockGroups;

if (!blockGroups || blockGroups.length === 0) {
  return [{ json: { success: true, message: 'No blocks to append' } }];
}

const results = [];
for (let i = 0; i < blockGroups.length; i++) {
  results.push({
    json: {
      groupIndex: i,
      groupSize: blockGroups[i].length,
      pageId: pageId,
      blocks: blockGroups[i]
    }
  });
}

return results;
